using System.Windows;
using Tune.Helpers;
using Tune.Helpers.DialogExtentions;
using Tune.Models.Music;
using Tune.Models.NewDialog;
using Tune.Models.Playlist;
using Tune.Persistence.PlaylistStorage;
using Tune.Values.Static;

// Initially generated by AI, but edited.
namespace Tune.Components.UI
{
    /// <summary>
    /// Dialog content: favorite a music into a playlist.
    /// Argument = (music, initially-selected playlist).
    /// Result   = the playlist the music was finally saved into (null on cancel).
    /// </summary>
    public partial class FavoriteMusic : DialogContentBase
    {
        // ==== Dependencies ====
        private PlaylistService? _service;

        // ==== Dialog Contract ====
        /// <summary>
        /// Input. The setter also refreshes the description text shown to the user.
        /// </summary>
        private (Music, PlaylistBase?) _argument;
        public (Music, PlaylistBase?) Argument
        {
            get => _argument;
            set
            {
                _argument = value;
                DescriptionTextBlock.Text =
                    value.Item1 != null && !string.IsNullOrEmpty(value.Item1.Metadata.Title)
                        ? value.Item1.Metadata.Title
                        : Strings.NO_CONTENT;
            }
        }

        /// <summary>
        /// Output. The playlist the music was saved into; null on cancel.
        /// </summary>
        public PlaylistBase? Result { get; set; }

        // ==== Constructor ====
        /// <summary>
        /// UI-only construction. No business logic and no Confirm/Cancel here,
        /// because no subscriber is attached yet.
        /// </summary>
        public FavoriteMusic()
        {
            InitializeComponent();
            DataContext = this;
            Height = 220;
            Width = 800;

            ConfirmButton.Click += OnConfirmClick;
            CancelButton.Click += OnCancelClick;
            // SelectOtherPlaylistButton wiring stays in XAML (or add it here).
        }

        // ==== Lifecycle ====
        /// <summary>
        /// Called by DialogService after the host window is loaded and
        /// after CloseRequested has been subscribed. It is safe to call
        /// Cancel()/Confirm() from here.
        /// </summary>
        protected override void OnShown()
        {
            _service = LoadableServicesHelper.GetPlaylistService();
            if (_service == null)
            {
                MessageBox.Show(
                    "Not loaded service or service not exists.",
                    Strings.APPLICATION_NAME,
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                Cancel();
                return;
            }

            // If the caller did not pre-select a playlist, ask the user to pick one.
            if (Argument.Item2 == null && SelectOtherPlaylist() == null)
            {
                Cancel();
            }
        }

        // ==== UI Logic ====
        private void OnConfirmClick(object sender, RoutedEventArgs e)
        {
            if (_service == null)
                return;

            if (Argument.Item2 == null)
            {
                MessageBox.Show(
                    "Unreachable but triggered: Given playlist is null & confirm",
                    Strings.APPLICATION_NAME,
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            Result = Argument.Item2;

            var saveResult = _service.SavePlaylist(Result);
            if (!saveResult.Success)
            {
                // TODO SHOW_TOAST
                MessageBox.Show(
                    $"Failed to save this music: {saveResult.ErrorMessage}",
                    Strings.APPLICATION_NAME,
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            Confirm();
        }

        private void OnCancelClick(object sender, RoutedEventArgs e)
        {
            Result = null;
            Cancel();
        }

        private void OnSelectOtherPlaylistClick(object sender, RoutedEventArgs e)
        {
            SelectOtherPlaylist();
        }

        /// <summary>
        /// Opens a sub-dialog to let the user pick another playlist.
        /// </summary>
        public PlaylistBase? SelectOtherPlaylist()
        {
            var setter = new SelectPlaylist();
            var newPlaylist = setter.ShowSelectPlaylistDialog("选择歌单来收藏");
            if (newPlaylist != null && _service != null)
            {
                newPlaylist.AddMuisc(Argument.Item1);
                var result = _service.SavePlaylist(newPlaylist);
                if (!result.Success)
                {
                    // TODO SHOW_TOAST
                    MessageBox.Show($"Failed to save this music: {result.ErrorMessage}", Strings.APPLICATION_NAME, MessageBoxButton.OK, MessageBoxImage.Information);
                    return null;
                }
                Result = newPlaylist;
                Confirm();
                return newPlaylist;
            }
            return null;
        }
    }
}